python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X = train.drop('target', axis=1).values; y = train['target'].values; 
for i in range(50):
    fv = X[:, i]
    th = np.median(fv)
    acc = max((fv >= th).astype(int) == y).mean(), ((fv < th).astype(int) == y).mean())
    if acc > 0.505: print(f'feat {i}: {acc}')"

python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X = train.drop('target', axis=1).values; y = train['target'].values; 
for i in range(50):
    for j in range(i+1, 50):
        preds = ((X[:, i] > 0) != (X[:, j] > 0)).astype(int)
        acc = max((preds == y).mean(), (1-preds == y).mean())
        if acc > 0.505: print(f'XOR {i}, {j}: {acc}')"

python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X = train.drop('target', axis=1).values; y = train['target'].values; 
best_acc = 0; best_split = None
for i in range(50):
    fv = X[:, i]
    thrs = np.percentile(fv, np.linspace(5, 95, 10))
    for th in thrs:
        for d in [1, -1]:
            acc = ((fv * d >= th * d).astype(int) == y).mean()
            if acc > best_acc:
                best_acc = acc; best_split = (i, th, d)
print(best_split, best_acc)"

